// Abbinamento incassi <-> parcelle.
// PRINCIPIO: e' automatico solo cio' che e' certo. Tutto il resto e' una PROPOSTA.
// Un abbinamento sbagliato e' silenzioso e si paga mesi dopo.

const movimenti = $('Movimenti bancari in entrata').all().map(i => i.json).filter(m => Number(m.importo) > 0);
const parcelle  = $('Parcelle aperte').all().map(i => i.json);

const cent = (v) => Math.round(Number(v) * 100);
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

const residuo = (p) => cent(p.totale) - cent(p.incassato || 0);

const risultati = [];

for (const mov of movimenti) {
  const imp = cent(mov.importo);
  const causale = norm(mov.causale);

  // 1. importo esatto + numero fattura nella causale -> AUTOMATICO
  const perNumero = parcelle.filter(p => residuo(p) === imp && causale.includes(norm(p.numero)));
  if (perNumero.length === 1) {
    risultati.push({ json: { esito: 'automatico', criterio: 'numero_fattura', movimento: mov, parcella_id: perNumero[0].parcella_id, client_id: perNumero[0].client_id, importo: mov.importo } });
    continue;
  }

  // 2. importo esatto + IBAN ordinante gia' noto per quel cliente -> AUTOMATICO
  const perIban = parcelle.filter(p => residuo(p) === imp && p.iban_noto && norm(p.iban_noto) === norm(mov.iban_ordinante));
  if (perIban.length === 1) {
    risultati.push({ json: { esito: 'automatico', criterio: 'iban_noto', movimento: mov, parcella_id: perIban[0].parcella_id, client_id: perIban[0].client_id, importo: mov.importo } });
    continue;
  }

  // 3. somma di piu' parcelle dello stesso cliente -> PROPOSTA
  const perCliente = {};
  for (const p of parcelle) {
    (perCliente[p.client_id] = perCliente[p.client_id] || []).push(p);
  }
  let proposta = null;
  for (const [clientId, lista] of Object.entries(perCliente)) {
    const somma = lista.reduce((t, p) => t + residuo(p), 0);
    if (somma === imp && lista.length > 1) {
      proposta = { client_id: clientId, parcelle: lista.map(p => p.parcella_id) };
      break;
    }
  }
  if (proposta) {
    risultati.push({ json: { esito: 'proposta', criterio: 'somma_parcelle', movimento: mov, ...proposta, importo: mov.importo } });
    continue;
  }

  // 4. importo parziale su una sola parcella plausibile -> PROPOSTA
  const parziali = parcelle.filter(p => residuo(p) > imp && causale.includes(norm(p.numero)));
  if (parziali.length === 1) {
    risultati.push({ json: { esito: 'proposta', criterio: 'incasso_parziale', movimento: mov, parcella_id: parziali[0].parcella_id, client_id: parziali[0].client_id, importo: mov.importo } });
    continue;
  }

  // 5. nessuna corrispondenza -> CODA MANUALE
  risultati.push({ json: { esito: 'manuale', criterio: 'nessuna_corrispondenza', movimento: mov, importo: mov.importo } });
}

return risultati;
